rows=[
('Xem và tìm kiếm sản phẩm','Khách vãng lai, USER','Có sản phẩm đang bán.', 'Mở cửa hàng;Nhập từ khóa, danh mục hoặc khoảng giá;Chọn cách sắp xếp và trang;Hệ thống hiển thị sản phẩm phù hợp', 'Không có kết quả: hiển thị danh sách trống, cho phép đổi bộ lọc.', 'Người mua xem được danh mục theo điều kiện đã chọn.', 'shop_products, product_variants, product_reviews', 'ShopExperienceController.java; /shop, /app/shop'),
('Xem chi tiết và chọn phân loại','Khách vãng lai, USER','Sản phẩm đang hoạt động.', 'Mở chi tiết sản phẩm;Xem ảnh, mô tả và đánh giá;Chọn tổ hợp phân loại;Hệ thống hiển thị giá và tồn tương ứng', 'Biến thể ngừng bán/hết tồn: không thêm hợp lệ vào giỏ. Sản phẩm không có biến thể: dùng giá và tồn của sản phẩm.', 'Xác định đúng sản phẩm/biến thể trước khi mua.', 'shop_products, product_variants, product_attributes, product_attribute_values, variant_attribute_values, product_reviews', 'ProductDetailView.vue; ProductVariantService.java; /shop/product/:id'),
('Quản lý giỏ hàng','Khách vãng lai, USER','Sản phẩm/biến thể hợp lệ; khách có thể chưa đăng nhập.', 'Chọn sản phẩm, phân loại và số lượng;Thêm vào giỏ;Mở giỏ, sửa số lượng hoặc xóa dòng;Hệ thống cập nhật tổng tiền tạm tính', 'Khách vãng lai lưu giỏ cục bộ và phải đăng nhập để thanh toán. Máy chủ kiểm tra lại giá, quyền sở hữu dòng giỏ và tồn kho; dữ liệu hiển thị cũ không đảm bảo còn hàng.', 'Giỏ phản ánh lựa chọn hiện tại; chưa tạo đơn.', 'shop_cart_items, shop_products, product_variants; giỏ khách trong trình duyệt', 'ShopController.java; ShopService.java; PublicShopView.vue'),
('Quản lý sản phẩm yêu thích','Khách vãng lai, USER','Sản phẩm tồn tại.', 'Chọn biểu tượng yêu thích;Hệ thống lưu lựa chọn;Mở danh sách yêu thích;Bỏ đánh dấu khi không còn cần', 'Khách lưu cục bộ; sau đăng nhập/đăng ký, dữ liệu được đồng bộ theo xử lý của ứng dụng.', 'Cập nhật cờ wishlisted, dùng chung bảng với lần xem gần nhất.', 'customer_product_states, shop_products', 'ShopCustomerService.java; useShopCustomer.js'),
('Xem sản phẩm đã xem gần đây','Khách vãng lai, USER','Có thao tác xem sản phẩm.', 'Mở chi tiết sản phẩm;Hệ thống ghi nhận lần xem;Mở khu vực đã xem;Chọn lại sản phẩm cần tham khảo', 'Chưa xem sản phẩm: không có lịch sử. Dữ liệu khách nằm ở trình duyệt; tài khoản dùng trạng thái theo người dùng.', 'Lưu lần xem gần nhất, không tạo bảng lịch sử riêng cho từng lượt.', 'customer_product_states, shop_products', 'ShopCustomerService.java; useShopCustomer.js'),
('So sánh sản phẩm','Khách vãng lai, USER','Có sản phẩm trong danh mục.', 'Chọn sản phẩm để so sánh;Mở giao diện so sánh;Đối chiếu các thông tin hiển thị;Bỏ sản phẩm khỏi danh sách khi cần', 'Chưa đủ lựa chọn hoặc vượt giới hạn giao diện: xử lý theo thông báo của giao diện; không ghi thêm bảng so sánh.', 'Người mua có thông tin để chọn sản phẩm.', 'shop_products; trạng thái so sánh ở giao diện', 'gym-frontend/src/components/shop; useShopCustomer.js'),
('Quản lý địa chỉ nhận hàng','USER','Đã đăng nhập.', 'Mở sổ địa chỉ;Nhập người nhận, điện thoại và địa chỉ;Chọn mặc định nếu cần;Lưu, sửa hoặc xóa địa chỉ thuộc tài khoản', 'Thiếu trường bắt buộc, quá giới hạn 20 địa chỉ hoặc địa chỉ của người khác: từ chối.', 'Sổ địa chỉ và địa chỉ mặc định được cập nhật.', 'customer_addresses', 'ShopCustomerService.java; ShopExperienceController.java'),
('Áp dụng mã giảm giá','Khách vãng lai, USER, STAFF, ADMIN','Có hàng được chọn và mã cần kiểm tra.', 'Xem hoặc nhập mã;Hệ thống kiểm tra thời hạn, trạng thái, lượt dùng và phạm vi;Tính phần giảm trên hàng đủ điều kiện;Hiển thị tổng tiền dự kiến', 'Mã hết hạn/hết lượt, không đủ giá trị hoặc sai phạm vi: thông báo không áp dụng. Việc xem trước chưa thay thế kiểm tra lúc tạo đơn.', 'Mã hợp lệ được đưa vào yêu cầu đặt hàng/bán tại quầy.', 'vouchers, voucher_scope_products, shop_products', 'VoucherService.java; ShopController.java; PosService.java'),
('Đặt hàng trực tuyến','USER','Đã đăng nhập; giỏ có hàng; có thông tin nhận.', 'Mở thanh toán;Chọn/nhập địa chỉ, mã giảm giá và phương thức;Gửi yêu cầu đặt hàng;Máy chủ kiểm tra hàng, khóa dữ liệu tồn và tính lại tiền;Tạo đơn, chi tiết và nhật ký, trừ tồn;Xóa giỏ sau khi lưu thành công và trả thông tin đơn', 'Giỏ trống, hàng ngừng bán, thiếu tồn/địa chỉ, voucher sai hoặc phương thức chưa bật: từ chối và không chốt đơn. COD tạo CONFIRMED; các phương thức trả trước tạo PENDING_PAYMENT.', 'Đơn và thông tin hàng tại thời điểm mua được lưu; chưa mặc nhiên là đã thu tiền.', 'shop_orders, shop_order_items, shop_cart_items, shop_products, product_variants, vouchers, shop_order_events, shop_inventory_movements', 'ShopService.checkout; POST /api/shop/orders'),
('Thanh toán đơn trực tuyến','USER; cổng thanh toán (phụ)','Có đơn thuộc người dùng, đang chờ thanh toán; phương thức được cấu hình.', 'Mở thông tin thanh toán của đơn;Với chuyển khoản, xem QR/nội dung; với ví, tạo phiên và mở URL thanh toán;Người mua thực hiện thanh toán;Hệ thống nhận/xác nhận kết quả qua luồng phù hợp;Cập nhật trạng thái và lịch sử khi xác nhận hợp lệ', 'Ví chưa cấu hình: không khả dụng. Callback ví sai chữ ký/merchant/số tiền: từ chối. Callback lặp: không ghi thu tiền lần hai. Tiền đến sau hủy/hết hạn: ghi sự kiện đối soát. QR hết hạn sau 15 phút; trang chuyển hướng không chứng minh đã trả tiền.', 'Đơn chỉ được ghi đã thanh toán khi kết quả được xác nhận hợp lệ. COD thu tiền ở luồng giao hàng, không gọi cổng thanh toán.', 'shop_orders, shop_order_events; hoàn tồn khi hết hạn có shop_inventory_movements', 'ShopPaymentService.java; ShopPaymentController.java; ShopExpiryScheduler.java'),
('Theo dõi và tra cứu đơn hàng','Khách vãng lai, USER','Có đơn; tài khoản cần quyền sở hữu hoặc người tra cứu có mã đơn và số điện thoại khớp.', 'Mở lịch sử đơn của tài khoản hoặc trang tra cứu;Chọn đơn hoặc nhập mã đơn và số điện thoại;Hệ thống kiểm tra quyền/thông tin;Hiển thị hàng, phân loại, tổng tiền, trạng thái và lịch sử', 'Sai mã/điện thoại hoặc không có quyền: từ chối. Khách được tra cứu không đồng nghĩa được đặt đơn trực tuyến không đăng nhập.', 'Người mua biết trạng thái đơn, không thay đổi đơn.', 'shop_orders, shop_order_items, shop_order_events', 'ShopService.lookupOrder/myOrders/order; /tra-cuu-don'),
('Hủy đơn hàng','USER','Là chủ đơn; đơn PENDING_PAYMENT hoặc COD đang CONFIRMED.', 'Mở đơn đủ điều kiện;Yêu cầu hủy;Hệ thống khóa đơn và kiểm tra lại điều kiện;Hoàn tồn, chuyển CANCELLED và ghi nhật ký;Hiển thị trạng thái mới', 'Đơn đã xử lý/không thuộc tài khoản: từ chối. Yêu cầu lặp không được hoàn tồn thêm lần nữa.', 'Đơn hủy và lượng tồn được trả lại đúng một lần.', 'shop_orders, shop_order_items, shop_products, product_variants, shop_order_events, shop_inventory_movements', 'ShopService.cancel'),
('Đánh giá sản phẩm sau mua','USER','Đơn thuộc tài khoản và chứa sản phẩm; online DELIVERED/COMPLETED hoặc POS PAID/COMPLETED.', 'Chọn sản phẩm trong đơn đủ điều kiện;Nhập 1–5 sao, nhận xét và ảnh tùy chọn;Gửi đánh giá;Hệ thống kiểm tra và lưu;Đánh giá xuất hiện trong danh sách sản phẩm', 'Đã đánh giá cùng người/đơn/sản phẩm, sai chủ đơn, sai trạng thái hoặc số sao: từ chối. Tối đa 8 ảnh; ảnh tải lên JPG/PNG/WebP, tối đa 5 MB mỗi ảnh.', 'Lưu đánh giá và danh sách URL ảnh.', 'product_reviews, shop_orders, shop_order_items, users, shop_products', 'ProductReviewService.java; ShopExperienceController.image'),
('Quản lý sản phẩm cửa hàng','ADMIN','Đăng nhập có quyền quản trị.', 'Mở danh sách quản lý;Tạo hoặc chọn sản phẩm;Cập nhật thông tin, giá, ảnh, tồn và trạng thái;Lưu;Hệ thống cập nhật danh mục và nhật ký tồn khi có thay đổi', 'Dữ liệu không hợp lệ: từ chối. Thao tác ngừng bán dùng cờ trạng thái; không mô tả là xóa lịch sử đơn.', 'Danh mục được cập nhật; giữ được thông tin đơn đã chốt.', 'shop_products, shop_inventory_movements', 'ShopService.saveProduct/hideProduct; /admin/shop'),
('Quản lý thuộc tính và biến thể','ADMIN','Đăng nhập quản trị; có sản phẩm cần phân loại.', 'Tạo/chọn thuộc tính và giá trị;Tạo tổ hợp biến thể cho sản phẩm;Nhập SKU, giá riêng và tồn;Lưu hoặc cập nhật trạng thái biến thể;Hệ thống dùng biến thể cho giỏ, online và POS', 'Biến thể không hợp lệ hoặc không thuộc sản phẩm: từ chối theo dịch vụ. Biến thể ngừng bán không bị xóa khỏi lịch sử mua.', 'Thuộc tính, tổ hợp giá trị, giá và tồn của biến thể được lưu.', 'product_attributes, product_attribute_values, product_variants, variant_attribute_values, shop_inventory_movements', 'ProductAttributeService.java; ProductVariantService.java; /admin/product-attributes'),
('Quản lý mã giảm giá','ADMIN','Đăng nhập quản trị.', 'Mở quản lý voucher;Nhập mã, loại và mức giảm;Đặt thời gian, giới hạn lượt, điều kiện và phạm vi;Lưu hoặc chỉnh trạng thái;Hệ thống dùng cấu hình khi kiểm tra mã mua hàng', 'Mã/điều kiện không hợp lệ: trả lỗi theo dịch vụ. Phạm vi sản phẩm được lưu ở bảng collection; không có thêm bảng khuyến mãi riêng.', 'Voucher và phạm vi áp dụng được cập nhật.', 'vouchers, voucher_scope_products', 'VoucherService.java; VoucherAdmin.vue'),
('Xử lý đơn hàng trực tuyến','STAFF, ADMIN','Đăng nhập có quyền; đơn tồn tại.', 'Mở danh sách đơn;Xem hàng và lịch sử;Chọn trạng thái tiếp theo hợp lệ;Hệ thống kiểm tra chuyển trạng thái;Lưu đơn và sự kiện', 'Chuyển trạng thái sai: từ chối. COD đi CONFIRMED → PREPARING → SHIPPING → DELIVERED → COMPLETED; ghi paid_at khi xác nhận giao/thu tiền. Không tự coi mọi đơn CONFIRMED là đã trả tiền.', 'Trạng thái và lịch sử đơn phản ánh xử lý vận hành.', 'shop_orders, shop_order_events; shop_inventory_movements nếu hoàn tồn', 'ShopService.updateStatus; PUT /api/shop/admin/orders/{id}/status'),
('Bán hàng tại quầy','STAFF, ADMIN','Đăng nhập có quyền bán; có ít nhất một dòng hàng.', 'Chọn tài khoản khách hoặc nhập tên khách vãng lai;Chọn sản phẩm, phân loại và số lượng;Nhập phương thức thanh toán và mã giảm giá nếu có;Xác nhận bán;Hệ thống kiểm tra tồn, tính tiền, tạo đơn POS và trừ tồn', 'Thiếu thông tin khách, số lượng không dương, dòng trùng, thiếu/sai phân loại hoặc thiếu tồn: từ chối. Không thêm tiền điều kiện “bắt buộc đang vào ca” vì PosService hiện không kiểm tra điều này.', 'Lưu đơn POS, nhân viên tạo, chi tiết hàng và nhật ký tồn.', 'shop_orders, shop_order_items, shop_products, product_variants, vouchers, shop_order_events, shop_inventory_movements', 'PosService.java; PosController.java'),
('Xem báo cáo cửa hàng','ADMIN','Đăng nhập quản trị.', 'Mở báo cáo;Chọn khoảng ngày;Hệ thống tổng hợp đơn theo ngày tạo;Hiển thị doanh thu online/POS, theo ngày và hàng bán chạy', 'Ngày kết thúc trước ngày bắt đầu: từ chối. Không có dữ liệu: hiển thị số liệu trống/0. Chỉ cộng đơn có paid_at và không CANCELLED/EXPIRED.', 'Xem báo cáo; không tạo bảng tổng hợp. Doanh thu gồm phí vận chuyển, trừ giảm giá; chưa phải lợi nhuận.', 'shop_orders, shop_order_items', 'ShopExperienceController.statistics; /admin/shop-reports'),
('Theo dõi tồn thấp và nhật ký kho','ADMIN','Đăng nhập quản trị.', 'Mở báo cáo/kho;Xem sản phẩm hoặc biến thể hoạt động có tồn ≤ 5;Lọc nhật ký theo sản phẩm và trang;Xem tồn trước/sau, lý do và đơn liên quan', 'Chưa có lịch sử: danh sách trống. Nhật ký chỉ có từ khi triển khai, không dựng lại dữ liệu cũ.', 'Quản trị biết hàng cần bổ sung và nguồn thay đổi tồn.', 'shop_inventory_movements, shop_products, product_variants', 'ShopExperienceController.inventory; ShopAuditService.java'),
('Phân công và xem lịch làm việc','ADMIN','Đăng nhập quản trị; có tài khoản được phân công.', 'Mở lịch làm việc;Chọn nhân viên, ngày, giờ bắt đầu/kết thúc;Lưu ca;Hệ thống trả ca được phân công;Quản trị xem danh sách lịch', 'Không tìm thấy tài khoản hoặc giờ kết thúc trước bắt đầu: từ chối. Không mô tả đã chống trùng ca khi code chưa có kiểm tra tương ứng.', 'Tạo work_shifts để nhân viên theo dõi và vào/kết ca.', 'work_shifts, users', 'WorkShiftService.assign; WorkShiftController.java'),
('Vào ca làm việc','STAFF, ADMIN','Có ca được phép thao tác và chưa check-in.', 'Mở lịch ca;Chọn ca;Nhập tiền mặt đầu ca;Gửi check-in;Hệ thống ghi thời điểm và trạng thái vào ca', 'Không sở hữu ca và không phải quản trị, hoặc đã check-in: từ chối. Không nhập tiền đầu ca: mã hiện tại dùng 0.', 'Ghi check_in_at, cash_at_start và trạng thái CHECKED_IN.', 'work_shifts', 'WorkShiftService.checkIn/owned'),
('Kết ca và đối soát tiền','STAFF, ADMIN','Ca được phép thao tác, đã vào ca và chưa kết ca.', 'Mở ca đang làm;Nhập tiền mặt kiểm đếm và ghi chú;Gửi kết ca;Hệ thống tổng hợp doanh thu POS theo nhân viên/khoảng thời gian của ca;Tính tiền mặt dự kiến và chênh lệch;Lưu kết ca', 'Chưa vào ca, đã kết ca hoặc không có quyền: từ chối. Chênh lệch được lưu để đối soát, không tự điều chỉnh đơn.', 'Lưu doanh thu tiền mặt/chuyển khoản, tiền dự kiến, kiểm đếm, chênh lệch và trạng thái COMPLETED.', 'work_shifts, shop_orders', 'WorkShiftService.checkOut')]
assert len(rows)==23
md=['# Bổ sung Use Case cửa hàng và nhân viên','',
'Tài liệu bổ sung cho SD-41_DATNSP26 (1).pdf, đối chiếu mã hiện tại ngày 17/09/2026. Bản đặc tả 43 bảng trước đó mới nêu danh sách chức năng cần cập nhật, chưa thay thế phần Use Case. Tài liệu này bổ sung danh mục, tác nhân, đặc tả và nguồn sơ đồ cho phạm vi cửa hàng/ca làm.',
'','## 1. Cách ghép vào báo cáo','',
'Giữ mã UC-01 đến UC-32 ở trang 18–20 để tránh làm hỏng tham chiếu cũ. Thêm 23 ca sử dụng dưới đây từ UC-33 đến UC-55 vào mục 2.2.2 và đưa đặc tả vào Phụ lục A. Số 55 là danh mục cũ cộng phần bổ sung cửa hàng/ca làm; không phải tuyên bố đã kiểm toán đầy đủ mọi chức năng khác như nhân vật đồng hành hay chatbot.',
'',
'Cập nhật mục 2.2.1 với khách vãng lai, hội viên USER, nhân viên STAFF, quản trị ADMIN và cổng thanh toán. Các mã cũ UC-01/UC-28 cần ghi nhận đăng nhập/đăng xuất cho STAFF; quyền quản trị không có nghĩa được tự đăng ký tài khoản ADMIN. UC-14 giữ phạm vi thanh toán gói tập, UC-42 dành cho đơn cửa hàng. UC-15/UC-25 là hỗ trợ trực tiếp; không dùng hai mã này để mô tả chatbot USER/BOT. UC-17 và UC-27 đang có phạm vi chồng lấn: cần thống nhất nội dung trước khi gộp/đánh lại mã.',
'','## 2. Tác nhân','',
'| Tác nhân | Vai trò trong phần bổ sung |','|---|---|',
'| Khách vãng lai | Xem hàng, chọn phân loại, giỏ cục bộ, yêu thích/đã xem/so sánh và tra cứu bằng mã đơn + điện thoại. Cần đăng nhập để đặt hàng trực tuyến. |',
'| USER | Thực hiện các thao tác mua hàng; quản lý địa chỉ, đặt/thanh toán, theo dõi/hủy đơn và đánh giá hợp lệ. |',
'| STAFF | Bán POS, xử lý đơn và vào/kết ca được phép thao tác. |',
'| ADMIN | Quản lý danh mục, biến thể, voucher, báo cáo/kho và phân ca; API cũng cho phép bán POS, xử lý đơn và thao tác ca. |',
'| Cổng thanh toán | Tác nhân hệ thống bên ngoài của luồng MoMo/ZaloPay khi đã được cấu hình. Không áp dụng cho thu tiền COD. |',
'','## 3. Danh mục bổ sung','', '| Mã | Use Case | Tác nhân |','|---|---|---|']
for n,r in enumerate(rows,33):md+=[f'| UC-{n} | {r[0]} | {r[1]} |']
md+=['','## 4. Đặc tả chi tiết','']
for n,(name,actors,pre,flow,alt,result,tables,evidence) in enumerate(rows,33):
    md += [f'### UC-{n}. {name}','',f'Tác nhân: {actors}.',f'Mục tiêu: {result}',f'Tiền điều kiện: {pre}', 'Kích hoạt: tác nhân chọn chức năng tương ứng hoặc thực hiện thao tác nêu ở bước 1.','Luồng chính:']
    md += [f'{i}. {step}.' for i,step in enumerate(flow.split(';'),1)]
    md += ['Luồng thay thế/ngoại lệ: '+alt,'Hậu điều kiện thành công: '+result,'Dữ liệu liên quan: '+tables+'.','Đối chiếu mã/giao diện: '+evidence+'.','']
md += ['## 5. Sơ đồ và quan hệ UML','',
'Ba tệp PlantUML đi kèm chia theo mua hàng, quản trị/vận hành và ca làm. Các sơ đồ dùng cùng mã UC-33…UC-55. Nhãn tác nhân biểu thị vai trò nghiệp vụ; quyền truy cập chi tiết theo mục 2 và từng đặc tả.',
'',
'UC-40 Áp dụng mã giảm giá mở rộng UC-41 Đặt hàng trực tuyến và UC-50 Bán tại quầy khi người mua/nhân viên nhập mã. Trong PlantUML, mũi tên <<extend>> đi từ UC-40 đến UC-41 hoặc UC-50. Đăng nhập là tiền điều kiện cho các chức năng cần tài khoản, không vẽ mọi use case <<include>> Đăng nhập. Thanh toán trực tuyến là bước có thể thực hiện sau khi tạo đơn; không vẽ UC-41 luôn include UC-42 vì COD không thanh toán ngay. Hủy/đánh giá là mục tiêu độc lập có điều kiện trạng thái; không phải bước bắt buộc của mọi đơn.',
'',
'Scheduler hết hạn và việc trừ/hoàn tồn là xử lý nội bộ, không phải người dùng hay hệ thống bên ngoài để vẽ làm tác nhân. Database cũng không phải tác nhân. Không thêm use case hoàn tiền tự động hoặc mua online không đăng nhập vì chưa có chức năng tương ứng.',
'','## 6. Tiêu chí nghiệm thu để đưa vào phần kiểm thử','',
'Các tiêu chí dưới đây là trường hợp cần kiểm tra, không phải tuyên bố tất cả đã chạy đạt trong lần viết tài liệu. Các kết quả kiểm thử có sẵn giữ theo báo cáo nâng cấp trước đó.',
'','| Nhóm | Tình huống cần kiểm tra | Kết quả mong đợi |','|---|---|---|',
'| UC-34/35/41/50 | Hai biến thể cùng sản phẩm có giá/tồn khác nhau | Giỏ, đơn online và POS lưu đúng variant_id, tên phân loại, đơn giá và tồn của biến thể. |',
'| UC-41 | Hai người đặt phần tồn cuối hoặc dữ liệu giá cũ | Máy chủ kiểm tra lại, không bán vượt tồn và không lấy tổng tiền từ khách làm nguồn tin cậy. |',
'| UC-41/49 | Đơn COD | Không có paid_at khi mới CONFIRMED; chỉ ghi khi xác nhận giao/thu tiền. |',
'| UC-42 | Callback hợp lệ, sai chữ ký, sai số tiền, lặp hoặc đến muộn | Chỉ chấp nhận hợp lệ; không thu hai lần; tiền đến muộn được ghi đối soát. |',
'| UC-44 | Hủy đúng chủ/khác chủ, hủy lặp, hủy sau xử lý | Chỉ hủy trạng thái cho phép; tồn được hoàn đúng một lần. |',
'| UC-39 | Sửa/xóa địa chỉ khác người | Từ chối và không thay đổi địa chỉ người khác. |',
'| UC-45 | Đơn chưa giao, sản phẩm không thuộc đơn, đánh giá lặp | Từ chối; đánh giá hợp lệ có 1–5 sao và ảnh đúng giới hạn. |',
'| UC-51/52 | Đơn hủy/hết hạn, COD chưa thu tiền, biến thể tồn 5 | Không cộng sai doanh thu; tồn 5 được cảnh báo. |',
'| UC-54/55 | Kết ca chưa vào, kết ca lặp, tiền kiểm đếm khác dự kiến | Từ chối trạng thái sai; lưu đúng số chênh lệch khi kết ca hợp lệ. |',
'','## 7. Nguồn đối chiếu','',
'Báo cáo PDF: trang 18–20 chứa UC-01…UC-32. Mã nguồn chính: gym-management/src/main/java/com/example/gymmanagement/shop; gym-management/src/main/java/com/example/gymmanagement/shift; gym-frontend/src/views; gym-frontend/src/components/shop; gym-frontend/src/composables/useShopCustomer.js. Mã UC-33…UC-55 là số hiệu đề xuất để ghép báo cáo, không phải ID tồn tại trong code.']
(OUT/'Bo_sung_Use_Case.md').write_text('\n'.join(md),encoding='utf-8')
specs=[('Use_Case_mua_hang',range(33,46),['Khách vãng lai','USER','Cổng thanh toán']),('Use_Case_quan_tri',list(range(46,53))+[40],['STAFF','ADMIN']),('Use_Case_ca_lam',range(53,56),['STAFF','ADMIN'])]
for filename,ids,actors in specs:
    p=['@startuml','left to right direction','skinparam shadowing false','skinparam defaultFontName Arial']
    amap={a:'A'+str(i) for i,a in enumerate(actors)}
    for a,alias in amap.items():p += [f'actor "{a}" as {alias}']
    p+=['rectangle "GYMIFY - Cửa hàng và nhân viên" {']
    for n in ids:p += [f'usecase "UC-{n}\\n{rows[n-33][0]}" as UC{n}']
    p+=['}']
    for n in ids:
        for a,alias in amap.items():
            if a.lower() in rows[n-33][1].lower():p += [f'{alias} -- UC{n}']
    if 41 in ids:p+=['UC40 ..> UC41 : <<extend>>\\n(khi nhập mã)']
    if 50 in ids:p+=['UC40 ..> UC50 : <<extend>>\\n(khi nhập mã)']
    p+=['@enduml']
    (OUT/(filename+'.puml')).write_text('\n'.join(p),encoding='utf-8')
assert len({r[0] for r in rows})==23
print('Created 23 detailed use cases UC-33..55 and 3 PlantUML diagrams.')
